-- Fixed academy-wide learning policy. Historical works, files and versions remain intact.
UPDATE lms_feature_flags SET enabled=true,all_groups=true,group_ids='{}',version=version+1,updated_at=now();
UPDATE lms_group_runs SET access_until=NULL,version=version+1 WHERE access_until IS NOT NULL;
ALTER TABLE lms_school_settings ALTER COLUMN settings SET DEFAULT '{"crmPreparation": {"defaultFormat": null}, "maxFileMiB": 10, "studentQuotaGiB": 5, "schoolQuotaGiB": 20, "materialAccessDays": null, "achievementTemplates": [{"rule": "first_accepted", "title": "lmsAchievementFirstAccepted", "reason": "lmsAchievementFirstAccepted"}, {"rule": "first_project", "title": "lmsAchievementFirstProject", "reason": "lmsAchievementFirstProject"}, {"rule": "section_completed", "title": "lmsAchievementSectionCompleted", "reason": "lmsAchievementSectionCompleted"}, {"rule": "makeup_completed", "title": "portalMakeupComplete", "reason": "portalMakeupComplete"}, {"rule": "course_completed", "title": "lmsAchievementCourseCompleted", "reason": "lmsAchievementCourseCompleted"}]}'::jsonb;
UPDATE lms_school_settings SET settings=(settings-'workCalendar'-'childFinanceVisible') || jsonb_build_object(
  'maxFileMiB',10,'materialAccessDays',NULL,'achievementTemplates','[{"rule": "first_accepted", "title": "lmsAchievementFirstAccepted", "reason": "lmsAchievementFirstAccepted"}, {"rule": "first_project", "title": "lmsAchievementFirstProject", "reason": "lmsAchievementFirstProject"}, {"rule": "section_completed", "title": "lmsAchievementSectionCompleted", "reason": "lmsAchievementSectionCompleted"}, {"rule": "makeup_completed", "title": "portalMakeupComplete", "reason": "portalMakeupComplete"}, {"rule": "course_completed", "title": "lmsAchievementCourseCompleted", "reason": "lmsAchievementCourseCompleted"}]'::jsonb),version=version+1,updated_at=now();
-- Children retain learning access; financial records belong to adult learners and representatives.
UPDATE portal_student_links link SET permissions=link.permissions-'finance.read'
FROM portal_student_identity identity WHERE identity.student_id=link.student_id AND identity.classification<>'adult' AND link.kind='self' AND link.permissions ? 'finance.read';
